import numpy as np
import scipy.sparse as sp
import tensorflow as tf
N=5; F=4; C=2
X=np.random.randn(N,F).astype('float32')
A_sp=sp.csr_matrix((np.random.rand(N,N)>0.5).astype('float32'))
A_dense=A_sp.toarray().astype('float32')
y=tf.one_hot(np.random.randint(C,size=N), C).numpy().astype('float32')
mask=np.ones(N, dtype='float32')

class GATLike(tf.keras.layers.Layer):
    def __init__(self):
        super().__init__()
        self.w = self.add_weight(shape=(F,C), initializer='glorot_uniform')
    def call(self, inputs):
        x,a = inputs
        if isinstance(a, tf.SparseTensor):
            a = tf.sparse.to_dense(a)
        logits = tf.matmul(x, self.w)
        scores = tf.matmul(logits, logits, transpose_b=True)
        scores = tf.where(a > 0, scores, tf.fill(tf.shape(scores), tf.constant(-1e9, scores.dtype)))
        alpha = tf.nn.softmax(scores, axis=-1)
        return tf.matmul(alpha, logits)

class M(tf.keras.Model):
    def __init__(self):
        super().__init__(); self.g = GATLike()
    def call(self, inputs): return self.g(inputs)

for label, A in [('scipy', A_sp), ('dense', A_dense)]:
    print('\n', label)
    m=M(); m.compile(optimizer='adam', loss='categorical_crossentropy', weighted_metrics=['acc'])
    h=m.fit([X,A], y, sample_weight=mask, batch_size=N, epochs=1, shuffle=False, verbose=0)
    print('fit ok', h.history)
